{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Compassionate, confidential therapy in {{CITY}}, {{STATE}}. Individual and couples therapy for anxiety, trauma, and life transitions." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-lux">
  <header class="site-header">
    <div class="brand">
      <img src="assets/img/avatar.svg" alt="Therapist avatar" class="avatar">
      <div>
        <h1 class="business">{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>
    <nav class="nav">
      <button class="nav-toggle" aria-label="Toggle navigation">☰</button>
      <ul class="nav-list">
        <li><a href="about.html">About</a></li>
        <li><a href="specialties.html">Specialties</a></li>
        <li><a href="approach.html">Approach</a></li>
        <li><a href="fees.html">Fees</a></li>
        <li><a href="faq.html">Help</a></li>
        <li><a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- Hero: gallery-style with SVG art -->
    <section id="hero" class="hero">
      <figure class="hero-art">
        <img src="assets/img/hero.svg" alt="Abstract supportive shapes" />
      </figure>
      <div class="hero-copy">
        <h2>Therapy tuned for the practical work of living</h2>
        <p>With {{THERAPIST_NAME}}, {{LICENSE}} — I offer evidence-informed psychotherapy for anxiety, trauma, relationships, and transitions. Sessions are confidential and anchored to your goals.</p>
        <div class="hero-actions">
          <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
          <a href="contact.html" class="btn ghost">Contact</a>
        </div>
      </div>
    </section>

    <!-- Myth vs Truth section -->
    <section id="myth-vs-truth" class="panel">
      <h3>Common assumptions — and a clearer view</h3>
      <div class="grid myths">
        <article>
          <h4>Myth: Therapy is only for crises</h4>
          <p>Truth: Therapy can be preventive and growth-oriented. Many people come to explore patterns, build skills, or navigate life changes before things escalate.</p>
        </article>
        <article>
          <h4>Myth: I need to be "broken" to seek support</h4>
          <p>Truth: Therapy is a relationship that helps people cultivate resilience, not a label for weakness. Seeking help is a pragmatic step.</p>
        </article>
        <article>
          <h4>Myth: Your therapist will tell you what to do</h4>
          <p>Truth: I collaborate with you to clarify values, options, and experiments that fit your life. I do not prescribe medication or give medical advice.</p>
        </article>
      </div>
    </section>

    <!-- Pillars: core modalities and values -->
    <section id="pillars" class="gallery">
      <h3>Foundations of my work</h3>
      <div class="pillars-grid">
        <div class="pillar">
          <h4>Practical skills</h4>
          <p>CBT-informed tools for managing anxiety, sleep, and concentration — taught with real-world practice.</p>
        </div>
        <div class="pillar">
          <h4>Relational repair</h4>
          <p>Attachment-aware approaches to help with closeness, boundaries, and communication.</p>
        </div>
        <div class="pillar">
          <h4>Trauma-sensitive care</h4>
          <p>Stabilization, pacing, and choice-driven processing when needed; safety is the priority.</p>
        </div>
        <div class="pillar">
          <h4>Life transitions</h4>
          <p>Pragmatic planning for career changes, caregiving shifts, and identity exploration.</p>
        </div>
      </div>
      <p class="note">Modalities: {{MODALITIES}}</p>
    </section>

    <!-- Case studies (anonymized, narrative style) -->
    <section id="case-studies" class="case-studies">
      <h3>How change often looks</h3>
      <div class="cases">
        <figure class="case">
          <figcaption>
            <strong>Case A — Anxiety and work stress</strong>
            <p>Over 12 weeks we developed routines to reduce overwhelm, practiced targeted behavioral experiments, and introduced boundaries at work. The client reported increased concentration and calmer evenings.</p>
          </figcaption>
        </figure>
        <figure class="case">
          <figcaption>
            <strong>Case B — Relationship repair</strong>
            <p>Couple-focused sessions emphasized communication exercises, micro-habits for connection, and clearer agreements. Progress was incremental and measurable by shared rituals.</p>
          </figcaption>
        </figure>
        <figure class="case">
          <figcaption>
            <strong>Case C — Trauma recovery</strong>
            <p>Work began with stabilization and safety planning. Later we introduced paced processing and skill-building; gains were preserved through ongoing coping plans.</p>
          </figcaption>
        </figure>
      </div>
    </section>

    <!-- FAQ preview -->
    <section id="preview-faq" class="panel slim">
      <h3>Questions people often ask</h3>
      <ul class="faq-list">
        <li><strong>How long are sessions?</strong> Typical sessions are 50 minutes; extended sessions available by arrangement.</li>
        <li><strong>Are sessions confidential?</strong> Yes. I follow professional confidentiality standards; limits include immediate risk of harm or legal requirements.</li>
        <li><strong>Do you work with insurance?</strong> I provide receipts for out-of-network reimbursement; see Fees for details.</li>
      </ul>
      <a href="faq.html" class="btn outline">More questions</a>
    </section>

    <!-- Primary CTA strip -->
    <section id="cta" class="cta-strip">
      <div>
        <h3>Ready to start? A first session is a conversation.</h3>
        <p>If you’re unsure, a brief phone consult can help us decide if we’re a good fit.</p>
      </div>
      <div class="cta-actions">
        <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html" class="btn ghost">Email: {{EMAIL}}</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="footer-grid">
      <div>
        <p><strong>{{THERAPIST_NAME}}, {{LICENSE}}</strong></p>
        <p>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <p>Confidentiality note: Sessions are confidential and records are stored securely. Exceptions apply for imminent risk or as required by law.</p>
      </div>
      <div>
        <p>Scope & boundaries: I provide psychotherapy for non-emergency concerns. I do not prescribe medication. For med-related questions, please consult a prescriber.</p>
      </div>
    </div>
    <p class="copyright">© {{BUSINESS_NAME}} • <a href="privacy.html">Privacy</a> • <a href="contact.html">Contact</a></p>
    <p class="crisis">If you are in crisis or immediate danger, call local emergency services or a crisis line. This website is not a crisis service.</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
